fn ck(b:bool,s:&str)->R<()>{if b{Ok(())}else{Err(s.into())}}
fn val(p:&Path)->R<Value>{Ok(serde_json::from_slice(&fs::read(p)?)?)}
fn txt(p:&Path)->R<String>{Ok(fs::read_to_string(p)?)}
