fn norm(s:String)->Vec<String>{let mut a=s.lines().map(|s|s.split_whitespace().collect::<Vec<_>>().join(" ")).collect::<Vec<_>>();a.sort();a}
fn packages(s:&str)->R<BTreeSet<Vec<String>>>{
 let mut result=BTreeSet::new();
 for p in s.split("[[package]]").skip(1){
  let mut fields=Vec::new();
  for name in ["name","version","source","checksum"]{let prefix=format!("{name} = ");fields.push(p.lines().find_map(|l|l.strip_prefix(&prefix)).unwrap_or("").to_string());}
  ck(!fields[0].is_empty()&&!fields[1].is_empty(),"Identidad de dependencia incompleta")?;
  if !fields[2].is_empty(){result.insert(fields);}
 }ck(!result.is_empty(),"Dependencias ausentes")?;Ok(result)
}
